    ShutterbugPage(String id, String portrait, List<Line> lines) {
        this.id = id; this.portrait = portrait; this.lines = lines;
        if (id.equals("une_trade_camera")) trade = id; else trade = null;
        var name = new StringBuilder(); for (String part : id.split("_")) name.append(Character.toUpperCase(part.charAt(0))).append(part.substring(1)); title = name.toString();
    }
    public int width() { return this == TRADE ? 206 : this == INFO ? 212 : 276; }
    public int height() { return this == TRADE ? 196 : this == INFO ? 116 : 182; }
    public boolean voiced() { return this != INTRO_6 && this != INFO && this != TRADE; }
    public boolean tip() { return id.startsWith("une_tip_"); }
    public static ShutterbugPage randomTip(net.minecraft.util.RandomSource random) { return TIPS.get(random.nextInt(TIPS.size())); }
    public ShutterbugPage next(int button) {
        if (this == INFO) return switch (button) { case 0 -> INFO_SHALESPRING; case 1 -> INFO_BLIZZARD; case 2 -> INFO_SELF; case 3 -> INFO_INFECTION; case 4 -> INFO_RUBY; case 5 -> INFO_TRAIN; default -> null; };
        if (button != 0) return null;
        return switch (this) {
            case INTRO_1 -> INTRO_2; case INTRO_2 -> INTRO_3; case INTRO_3 -> INTRO_4; case INTRO_4 -> INTRO_5; case INTRO_5 -> INTRO_6;
            case INFO_SELF -> INFO_SELF_2; case INFO_SELF_2 -> INFO_SELF_3; case INFO_BLIZZARD -> INFO_BLIZZARD_2;
            case ERRAND_A -> ERRAND_B; case ERRAND_B -> ERRAND_C;
            default -> id.startsWith("une_info_") ? INFO : id.startsWith("une_errand_") ? MAIN : null;
        };
    }
    public record Line(String key, int x, int y, int color, int spacing) { public Line(String key, int x, int y, int color) { this(key, x, y, color, 0); } }
